// Masked - secure text display with character masking
public class Masked
{
    private readonly string _inner;
    private readonly char _maskChar;

    public Masked(string content, char maskChar = '*')

    public char MaskChar => _maskChar;
    public string Value => new string(_maskChar, _inner.Length);  // Masked representation

    // Conversions
    public static implicit operator string(Masked masked) => masked.Value;
    public static implicit operator Text(Masked masked) => Text.Raw(masked.Value);

    // Debug shows original, Display shows masked
    public override string ToString() => Value;  // Masked version
